import json, os
from pathlib import Path
p = Path(os.environ['VERIFIER_OUTPUT']) / 'research_answers.json'
questions = ['q1_multi_broker_reporting', 'q2_hft_cost_calculation', 'q3_software_naming']
fields = ['conclusion', 'citation_document', 'evidence_snippet', 'answer_text']
try:
    data = json.loads(p.read_text(encoding='utf-8'))
    details = {}
    ok = isinstance(data, dict)
    for q in questions:
        value = data.get(q) if isinstance(data, dict) else None
        missing = [f for f in fields if not isinstance(value, dict) or f not in value]
        details[q] = {'is_object': isinstance(value, dict), 'missing_fields': missing}
        ok = ok and isinstance(value, dict) and not missing
    observed = details
except Exception as e:
    ok = False
    observed = {'parse_error': type(e).__name__}
print(json.dumps({'status': 'pass' if ok else 'fail', 'observed': observed, 'evidence': {'required_fields_per_question': fields}}, ensure_ascii=False))

import json, os
from pathlib import Path
p = Path(os.environ['VERIFIER_OUTPUT']) / 'research_answers.json'
questions = ['q1_multi_broker_reporting', 'q2_hft_cost_calculation', 'q3_software_naming']
allowed = ['Yes', 'No', 'Unknown']
try:
    data = json.loads(p.read_text(encoding='utf-8'))
    values = {q: data.get(q, {}).get('conclusion') if isinstance(data.get(q), dict) else None for q in questions} if isinstance(data, dict) else {q: None for q in questions}
    invalid = {q: v for q, v in values.items() if v not in allowed}
    ok = not invalid
    observed = {'conclusions': values, 'invalid': invalid}
except Exception as e:
    ok = False
    observed = {'parse_error': type(e).__name__}
print(json.dumps({'status': 'pass' if ok else 'fail', 'observed': observed, 'evidence': {'allowed_conclusions': allowed}}, ensure_ascii=False))

